// NOTE: same code as ACarryableUnit::Create (004d7c40), folded in retail
TBOOL AUnitPoolBall::Create( AUnitTransform* a_pTransform )
{
	if ( !AAnimatedUnit::Create( a_pTransform ) )
		return TFALSE;

	m_eFlags |= FLAGS_AI_ENABLED;
	m_eFlags |= FLAGS_AI_ENABLED | FLAGS_THINK_ENABLED;

	return TTRUE;
}

// $Barnyard: FUNCTION 0041a5b0
void AUnitPoolBall::UpdateAI( TFLOAT a_fDeltaTime )
{
	ASteer* pSteer = m_pSteer;
	GetAnimatableObject()->GetModelInstance()->SetTransform( *pSteer->GetPosition(), TVector4::VEC_POSX );

	AVisibleUnit::UpdateAI( a_fDeltaTime );
}

// NOTE: a thunk to AVisibleUnit::Think (004d7ae0) shared by several classes in retail
TBOOL AUnitPoolBall::Think( TFLOAT a_fDeltaTime )
{
	return AVisibleUnit::Think( a_fDeltaTime );
}

// $Barnyard: FUNCTION 0041a5a0
void AUnitPoolBall::SetupSteer()
{
	m_pPoolSteer = TSTATICCAST( APoolBallSteer, m_pSteer );
}

// $Barnyard: FUNCTION 0041a2e0
TVector4 AUnitPoolBall::GetPosition()
{
	return *m_pPoolSteer->GetPosition();
}

// $Barnyard: FUNCTION 0041a320
void AUnitPoolBall::SetPosition( const TVector4& a_rcPosition )
{
	m_pPoolSteer->SetPosition( a_rcPosition );
}

// $Barnyard: FUNCTION 0041a340
TFLOAT AUnitPoolBall::GetRadius()
{
	return m_pPoolSteer->GetRadius();
}

// $Barnyard: FUNCTION 0041a350
TBOOL AUnitPoolBall::IsPlacementValid()
{
	return !m_pPoolSteer->IsTouchingOtherBall();
}

// $Barnyard: FUNCTION 0041a3d0
TINT AUnitPoolBall::GetSteerState()
{
	return m_pPoolSteer->GetState();
}

// $Barnyard: FUNCTION 0041a560
TINT AUnitPoolBall::GetFirstHitBallType()
{
	if ( !m_pPoolSteer->GetFirstHitUnit() )
		return BALLTYPE_NONE;

	TINT iBallType = TSTATICCAST( AUnitPoolBall, m_pPoolSteer->GetFirstHitUnit() )->m_iBallType;
	m_pPoolSteer->ResetFirstHitUnit();

	return iBallType;
}
